async function main(){const c=new Client({connectionString:process.env.DATABASE_PRIVATE_URL||process.env.DATABASE_URL,connectionTimeoutMillis:20000});await c.connect();try{const codes=rows.map(r=>r.order);const q=await c.query(`select o.order_code,o.account_name,o.status,o.fulfillment_location_id,o.shipped_carrier_name,o.shipped_tracking_reference,
(select coalesce(sum(l.requested_quantity),0)::numeric from portal_order_lines l where l.order_id=o.id) requested_qty,
(select coalesce(jsonb_agg(distinct t.tracking_number) filter(where t.tracking_number is not null),'[]'::jsonb) from warehouse_shipments s left join shipment_trackers t on t.warehouse_shipment_id=s.id where s.order_id=o.id) package_tracking
from portal_orders o where o.order_code=any($1::text[]) order by o.order_code`,[codes]);const by=new Map(q.rows.map(r=>[r.order_code,r]));const issues=[],verified=[];for(const source of rows){const o=by.get(source.order);if(!o){issues.push({order:source.order,reason:"ORDER_NOT_FOUND"});continue;}if(o.account_name!=="RANCHER'S CHIPS"||String(o.fulfillment_location_id)!=="1"){issues.push({order:source.order,reason:"SCOPE_MISMATCH"});continue;}const actual=new Set([String(o.shipped_tracking_reference||"").trim(),...(Array.isArray(o.package_tracking)?o.package_tracking:[])].filter(Boolean));const expected=source.tracking;const tracksMatch=expected.every(t=>actual.has(t));if(o.status!=="SHIPPED"||!tracksMatch||String(o.shipped_carrier_name||"").trim().toLowerCase()!==source.carrier.toLowerCase()||(source.qty!=null&&Number(o.requested_qty)!==source.qty)){issues.push({order:source.order,reason:o.status!=="SHIPPED"?"NOT_SHIPPED":!tracksMatch?"TRACKING_MISMATCH":String(o.shipped_carrier_name||"").trim().toLowerCase()!==source.carrier.toLowerCase()?"CARRIER_MISMATCH":"QUANTITY_MISMATCH"});}else verified.push(source.order);}console.log(JSON.stringify({audited:rows.length,verified:verified.length,issues}));}finally{await c.end();}}
